# 用法：把本文件内容保存为 install.sh，在目标机器执行 bash install.sh 即可
set -e
mkdir -p "$HOME/.workbuddy/skills"
echo "正在解压安装「引火生气盲派」skill ..."
B64=''
echo "$B64" | base64 -d | tar -xz -C "$HOME/.workbuddy/skills"
echo "✅ 安装完成 → $HOME/.workbuddy/skills/yinhuo-shengqi-mangpai"
